users = {1: {"id": 1, "name": "Ana"}, 2: {"id": 2, "name": "Beto"}}

def handle(method, uri, token=None):
    if token != "valid-token":
        return {"status": 401, "error": "missing or invalid token"}
    parts = uri.strip("/").split("/")
    if parts[0] != "users":
        return {"status": 404, "error": "unknown resource"}
    if len(parts) == 1 and method == "GET":
        return {
            "status": 200,
            "data": list(users.values()),
            "links": {"self": "/users"},
        }
    uid = int(parts[1])
    if method == "GET":
        user = users.get(uid)
        if not user:
            return {"status": 404, "error": "not found"}
        return {
            "status": 200,
            "data": user,
            "links": {"self": f"/users/{uid}", "delete": f"/users/{uid}"},
        }
    return {"status": 405, "error": "method not allowed"}


print(handle("GET", "/users", token=None))
print(handle("GET", "/users", token="valid-token"))
print(handle("GET", "/users/1", token="valid-token"))
print(handle("GET", "/users/9", token="valid-token"))
